// artifactExts are the only file extensions the /media surface serves from the
// artifact root — playlists, fMP4 init segments, and media fragments. Anything
// else is 404 (the surface is a playback surface, not a file browser).
var artifactExts = map[string]string{
	".m3u8": "application/vnd.apple.mpegurl",
	".m4s":  "video/iso.segment",
	".mp4":  "video/mp4",
}

// ServeHTTP is the token-gated playback surface (Interface 3): static file
// serving ONLY — playlists and segments from the artifact root under
// /media/<itemID>/<nonce>/..., originals through the injected Original
// resolver at /media/<itemID>/original with stdlib Range support. No sessions,
// no sessions, no media processes, no writes to library directories. Segments
// and init segments are byte-identical to the published file; playlists serve
// the published lines with every URI carrying the requesting token (see
// tokenizePlaylist — self-authorizing playlists for cookie-less clients).
// Every request must carry a valid media token
// (cookie primary, query fallback) naming the item on the path; the admin
// credential is not accepted here, and a rejection never echoes the token.
//
// Token values are never logged: this handler writes no request logs, and its
// only error texts are the static strings below.
func (s *Service) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		w.Header().Set("Allow", "GET, HEAD")
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	itemID, rest, ok := splitMediaPath(r.URL.Path)
	if !ok {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	tok := mediaToken(r)
	granted, err := s.verify(tok, timeNow())
	if err != nil || granted != itemID {
		http.Error(w, "valid media token required", http.StatusUnauthorized)
		return
	}
	if rest == "original" {
		s.serveOriginal(w, r, itemID)
		return
	}
	s.serveArtifact(w, r, itemID, rest, tok)
}

// mediaToken extracts the request's media token: the cookie first (D-6
// cookie-primary), the query parameter as the cookie-less fallback.
func mediaToken(r *http.Request) string {
	if c, err := r.Cookie(cookieName); err == nil && c.Value != "" {
		return c.Value
	}
	return r.URL.Query().Get(tokenQuery)
}

// splitMediaPath parses "/media/<itemID>/<rest>" (the mount prefix web.Options
// registers). ok is false for anything not shaped exactly so.
func splitMediaPath(p string) (itemID, rest string, ok bool) {
	p = strings.TrimPrefix(path.Clean("/"+p), mediaPrefix)
	p = strings.TrimPrefix(p, "/")
	itemID, rest, found := strings.Cut(p, "/")
	if !found || itemID == "" || rest == "" {
		return "", "", false
	}
	if !idCharset.MatchString(itemID) || itemID == "." || itemID == ".." {
		return "", "", false
	}
	return itemID, rest, true
}

// serveOriginal answers the direct floor: the item's original bytes with
// stdlib range/HEAD/304 handling (spec "Direct playback floor" — zero
// transform work, library directories read-only). Resolution goes through the
// injected Original resolver ONLY; anything unresolvable is 404.
func (s *Service) serveOriginal(w http.ResponseWriter, r *http.Request, itemID string) {
	if s.Original == nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	absPath, ok := s.Original(r.Context(), itemID)
	if !ok || absPath == "" {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	f, err := os.Open(absPath)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil || fi.IsDir() {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	http.ServeContent(w, r, filepath.Base(absPath), fi.ModTime(), f)
}

// serveArtifact answers a playlist/segment request from the artifact root:
// /media/<itemID>/<nonce>/<file> where file may additionally live under t/
// (the tail phase's segments). Every component is charset-guarded, the
// extension is whitelisted, and the resolved path is verified to stay under
// Root — the surface never serves anything it did not publish.
func (s *Service) serveArtifact(w http.ResponseWriter, r *http.Request, itemID, rest, token string) {
	nonce, name, found := strings.Cut(rest, "/")
	if !found || !s.artifactNameOK(nonce) {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	// The artifact name may span subdirectories (tail segments live under
	// t/): every component must be a safe name, and the extension whitelist
	// applies to the final one only.
	parts := strings.Split(name, "/")
	for _, part := range parts {
		if !s.artifactNameOK(part) {
			http.Error(w, "not found", http.StatusNotFound)
			return
		}
	}
	file := parts[len(parts)-1]
	ct, ok := artifactExts[strings.ToLower(filepath.Ext(file))]
	if !ok {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	final, err := s.buildDir(itemID, nonce)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	full := filepath.Join(final, filepath.FromSlash(name))
	if !strings.HasPrefix(full, filepath.Clean(s.Root)+string(filepath.Separator)) {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	f, err := os.Open(full)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil || fi.IsDir() {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	// Playlists grow until ENDLIST (a partial build is live-polled), so they
	// revalidate; segments and init segments are byte-identical per nonce and
	// cache immutably (D-5). Served playlists are rewritten so every URI they
	// reference carries the requesting token (self-authorizing playlists —
	// cookie-less TV clients, incident 2026-10-31); segments serve verbatim.
	w.Header().Set("Content-Type", ct)
	if strings.HasSuffix(file, ".m3u8") {
		w.Header().Set("Cache-Control", "no-cache")
		body, err := io.ReadAll(f)
		if err != nil {
			http.Error(w, "not found", http.StatusNotFound)
			return
		}
		w.Write(tokenizePlaylist(body, token))
		return
	}
	w.Header().Set("Cache-Control", "private, max-age=31536000, immutable")
	http.ServeContent(w, r, file, fi.ModTime(), f)
}

// artifactNameOK reports whether one artifact path component is a safe name
// (charset-guarded, no dot-dot, not an extension-less oddity).
func (s *Service) artifactNameOK(part string) bool {
	return part != "" && part != "." && part != ".." && idCharset.MatchString(part)
}
